    const rows = []
    for (let row = 0; row < 2; row++) {
      const px = []
      for (let i = 0; i < cell.w; i++) px.push(at(cell.x + i, cell.y + row))
      if (px.some((p) => p[3] < 128)) {
        rows.length = 0
        break
      }
      rows.push(px)
    }
    if (rows.length !== 2) continue
    // 眼睛必须真有对比：上一行是眼睛，下一行是瞳孔/眼白。
